ROOT=/home/agentops/.claude/jobs/2a487caa/tmp/legacy-runs && mkdir -p server/.tmp-legacy && cat > server/.tmp-legacy/compare.ts <<'EOF'
import { readFileSync } from 'node:fs'
import { parseProjectsConfig } from '../projectsConfig.ts'
import { RunStore } from '../projects.ts'
const root = process.argv[2]
const repo = process.cwd()
const nodes = JSON.parse(readFileSync(`${root}/before/project-workflows-001/run-state.json`, 'utf8')).definition
async function load(name: string) {
  const config = await parseProjectsConfig(JSON.stringify({ version: 1, projects: [{ project_id: 'p', name: 'P', repository: repo, workflows: [{ workflow_id: 'w', runs_root: `${root}/${name}`, definition: nodes }] }] }), name)
  const store = new RunStore(config)
  const scope = store.scope('p', 'w')
  const run = await store.loadRun(scope, 'project-workflows-001')
  return { detail: run.detail, review: run.review, inputs: run.inputs, events: run.events.length }
}
const before = await load('before')
const after = await load('after')
const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)
console.log('snapshot identical:', same(before.detail.snapshot, after.detail.snapshot))
console.log('definition identical:', same(before.detail.definition, after.detail.definition))
console.log('summary status:', before.detail.summary.status, after.detail.summary.status)
console.log('review identical:', same(before.review, after.review), 'findings:', after.review?.findings.map(f => f.worker))
console.log('inputs before:', before.inputs?.selected_workers, before.inputs?.excluded_workers, before.inputs?.workers.map(w => [w.node_id, w.launch_node_id, w.required_check_kinds]))
console.log('inputs after: ', after.inputs?.selected_workers, after.inputs?.excluded_workers, after.inputs?.workers.map(w => [w.node_id, w.launch_node_id, w.required_check_kinds]))
console.log('inputs identical:', same(before.inputs, after.inputs), 'events:', before.events, after.events)
console.log('nodes:', after.detail.snapshot.nodes.map(n => `${n.node_id}=${n.status}/${n.attempt}`).join(' '))
EOF
